`compose.yaml`
```yaml
# n8n-io/n8n#44762 race harness: n8n (main mode) -> toxiproxy -> postgres.
# IMAGE selects stock or patched; N8N_PORT / TOXI_PORT keep two stacks apart.
services:
  postgres:
    image: postgres:16-alpine
    environment: { POSTGRES_USER: n8n, POSTGRES_PASSWORD: n8n, POSTGRES_DB: n8n }
    healthcheck: { test: ["CMD", "pg_isready", "-U", "n8n"], interval: 2s, retries: 30 }
  toxiproxy:
    image: ghcr.io/shopify/toxiproxy:2.9.0
    command: ["-host=0.0.0.0", "-config=/toxiproxy.json"]
    volumes: ["./toxiproxy.json:/toxiproxy.json:ro"]
    ports: ["127.0.0.1:${TOXI_PORT}:8474"]
    depends_on: { postgres: { condition: service_healthy } }
  n8n:
    image: ${IMAGE}
    environment:
      DB_TYPE: postgresdb
      DB_POSTGRESDB_HOST: toxiproxy
      DB_POSTGRESDB_PORT: "6432"
      DB_POSTGRESDB_USER: n8n
      DB_POSTGRESDB_PASSWORD: n8n
      DB_POSTGRESDB_DATABASE: n8n
      EXECUTIONS_MODE: regular
      N8N_ENCRYPTION_KEY: harness-412-not-a-secret
      N8N_DIAGNOSTICS_ENABLED: "false"
      N8N_PERSONALIZATION_ENABLED: "false"
      N8N_LOG_LEVEL: info
      GENERIC_TIMEZONE: UTC
      DB_POSTGRESDB_POOL_SIZE: "10"
    volumes: ["./workflows:/workflows:ro"]
    ports: ["127.0.0.1:${N8N_PORT}:5678"]
    depends_on: [toxiproxy]
```

