`run.sh`
```bash
#!/usr/bin/env bash
# usage: run.sh <stock|patched> <n8n_port> <toxi_port> <latency_ms> <count> <spacing_s> <wait_min> <wait_max> <settle_s>
set -euo pipefail
name=$1 N8N_PORT=$2 TOXI_PORT=$3 LAT=$4 COUNT=$5 SPACING=$6 WMIN=$7 WMAX=$8 SETTLE=$9
case $name in stock) IMAGE=docker.n8n.io/n8nio/n8n:2.46.7;; patched) IMAGE=n8n-412:patched;; esac
export IMAGE N8N_PORT TOXI_PORT
cd "$(dirname "$0")"
out=results/$name-$(date -u +%Y%m%dT%H%M%SZ); mkdir -p "$out"
dc() { docker compose -p "race412-$name" "$@"; }
dc down -v >/dev/null 2>&1 || true
dc up -d postgres toxiproxy
dc run --rm -T n8n import:workflow --input=/workflows/child.json
dc run --rm -T n8n import:workflow --input=/workflows/parent.json
dc run --rm -T n8n publish:workflow --id=raceChild0000001
dc run --rm -T n8n publish:workflow --id=raceParent000001
dc up -d n8n
for i in $(seq 1 90); do curl -fsS "http://127.0.0.1:$N8N_PORT/healthz" >/dev/null 2>&1 && break; sleep 2; done
sleep 5
if [ "$LAT" -gt 0 ]; then
  curl -fsS -X POST "http://127.0.0.1:$TOXI_PORT/proxies/pg/toxics" \
    -d "{\"name\":\"lat\",\"type\":\"latency\",\"stream\":\"downstream\",\"attributes\":{\"latency\":$LAT}}" >/dev/null
fi
echo "image=$IMAGE latency_ms=$LAT count=$COUNT spacing_s=$SPACING wait=${WMIN}-${WMAX}s settle_s=$SETTLE started=$(date -u +%FT%TZ)" | tee "$out/params"
for i in $(seq 1 "$COUNT"); do
  w=$(( WMIN + RANDOM % (WMAX - WMIN + 1) ))
  curl -fsS -m 120 -X POST "http://127.0.0.1:$N8N_PORT/webhook/race-parent" -H 'content-type: application/json' -d "{\"wait\":$w,\"i\":$i}" >/dev/null || echo "fire $i failed"
  sleep "$SPACING"
done
sleep $(( WMAX + SETTLE ))
psql() { dc exec -T postgres psql -U n8n -d n8n -At -c "$1"; }
psql "select status, count(*) from execution_entity where \"workflowId\"='raceParent000001' group by status order by status" | tee "$out/parent-statuses"
psql "select id from execution_entity where \"workflowId\"='raceParent000001' and status='waiting' order by id" > "$out/stuck-ids"
psql "select status, count(*) from execution_entity where \"workflowId\"='raceChild0000001' and \"deletedAt\" is null group by status" | tee "$out/child-statuses"
dc logs --no-color n8n > "$out/n8n.log" 2>&1
{
  echo "stuck_parents=$(wc -l < "$out/stuck-ids")"
  echo "not_claimable=$(grep -c 'Parent execution not claimable' "$out/n8n.log" || true)"
  echo "no_longer_exist=$(grep -c 'waits on sub-executions that no longer exist' "$out/n8n.log" || true)"
  echo "harness_waited=$(grep -c 'harness-412' "$out/n8n.log" || true)"
} | tee "$out/summary"
echo "results in $out"
```

Build the patched image, then run both:
```bash
mkdir stock && for f in wait-tracker.js errors/execution-already-resuming.error.js; do
  docker run --rm --entrypoint cat docker.n8n.io/n8nio/n8n:2.46.7 /usr/local/lib/node_modules/n8n/dist/$f > stock/$(basename $f); done
cp -r stock patched && (cd patched && patch -p1 < ../port.diff)
docker build -f Dockerfile.patched -t n8n-412:patched .
./run.sh stock 5681 8481 500 90 7 70 130 180 & ./run.sh patched 5682 8482 500 90 7 70 130 180 & wait
```
`port.diff` is your diff applied to the compiled 2.46.7 files, plus the one `[harness-412]` log line.

